/**
 * Real-TeX fixtures (test/fixtures/<case>/<engine>.log, generated by test/fixtures/generate.mjs) against reviewed
 * expected outputs (<engine>.expected.json). `LOG_PARSER_UPDATE=1 npx vitest run` rewrites the expected files;
 * review every diff by hand before committing.
 */
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { parseLatexLog, type ParsedDiagnostic } from '../src/index.ts'

const FIXTURES = join(dirname(fileURLToPath(import.meta.url)), 'fixtures')
/** generate.mjs rewrites the build root to this (src/ is where latexmk runs). */
const ROOT_DIR = '/srv/ligature builds/b1/src'
const ENGINES = ['pdflatex', 'xelatex', 'lualatex'] as const
const UPDATE = process.env.LOG_PARSER_UPDATE === '1'

const cases = readdirSync(FIXTURES).filter(n => statSync(join(FIXTURES, n)).isDirectory()).sort()

function logsOf(c: string): string[] {
  return readdirSync(join(FIXTURES, c)).filter(f => f.endsWith('.log')).sort()
}

function parse(c: string, log: string): ParsedDiagnostic[] {
  return parseLatexLog(readFileSync(join(FIXTURES, c, log), 'utf8'), { rootDir: ROOT_DIR })
}

/** Without the raw excerpt, for the semantic checks below. */
function brief(c: string, log: string): Omit<ParsedDiagnostic, 'raw'>[] {
  return parse(c, log).map(({ raw: _raw, ...d }) => d)
}

describe('fixtures: every case has logs from all three engines', () => {
  it.each(cases)('%s', c => {
    const logs = logsOf(c)
    for (const e of ENGINES) expect(logs).toContain(`${e}.log`)
    expect(existsSync(join(FIXTURES, c, 'main.tex'))).toBe(true)
  })
})

describe('fixtures: expected outputs', () => {
  const all = cases.flatMap(c => logsOf(c).map(l => [c, l] as const))
  it.each(all)('%s/%s', (c, log) => {
    const got = parse(c, log)
    const file = join(FIXTURES, c, log.replace(/\.log$/, '.expected.json'))
    if (UPDATE) writeFileSync(file, JSON.stringify(got, null, 2) + '\n')
    const want = JSON.parse(readFileSync(file, 'utf8')) as unknown
    expect(got).toEqual(want)
  })
})

/** The same document must give the same diagnostics whatever the engine (where the engines agree). */
describe.each(ENGINES)('fixtures: semantics (%s)', engine => {
  const log = `${engine}.log`

  it('clean document: nothing', () => {
    expect(brief('clean', log)).toEqual([])
  })

  it('errors: file:line errors with culprits, package/class/latex kinds, system-file error attributed to main.tex', () => {
    expect(brief('errors', log)).toEqual([
      { severity: 'error', kind: 'latex', message: "Unknown option 'nosuchopt' for package xcolor.", path: 'main.tex' },
      { severity: 'error', kind: 'tex', message: 'Undefined control sequence \\undefinedmacro', path: 'main.tex', line: 4 },
      { severity: 'error', kind: 'tex', message: 'Undefined control sequence \\alsoundefined', path: 'main.tex', line: 6 },
      { severity: 'error', kind: 'tex', message: 'Missing $ inserted.', path: 'main.tex', line: 8 },
      { severity: 'error', kind: 'tex', message: 'Missing $ inserted.', path: 'main.tex', line: 9 },
      { severity: 'error', kind: 'latex', message: 'Environment nosuchenv undefined.', path: 'main.tex', line: 10 },
      { severity: 'error', kind: 'latex', message: '\\begin{document} ended by \\end{nosuchenv}.', path: 'main.tex', line: 12 },
      { severity: 'error', kind: 'package:xcolor', message: "Undefined color `nosuchcolor'.", path: 'main.tex', line: 14 },
      { severity: 'error', kind: 'latex', message: '\\begin{itemize} on input line 16 ended by \\end{enumerate}.', path: 'main.tex', line: 18 },
    ])
  })

  it('errors: latexmk console (several runs) gives the same, deduplicated', () => {
    expect(brief('errors', `${engine}.console.log`)).toEqual(brief('errors', log))
  })

  it('nested \\input/\\include from sub-folders (and a file name with a space) are attributed correctly', () => {
    expect(brief('nested', log)).toEqual([
      { severity: 'error', kind: 'tex', message: 'Undefined control sequence \\undefinedindeep', path: 'chapters/sections/deep.tex', line: 6 },
      { severity: 'error', kind: 'tex', message: 'Undefined control sequence \\undefinedinintro', path: 'chapters/intro.tex', line: 6 },
      { severity: 'error', kind: 'tex', message: 'Undefined control sequence \\undefinedinmain', path: 'main.tex', line: 7 },
      { severity: 'error', kind: 'tex', message: 'Undefined control sequence \\undefinedinincluded', path: 'chapters/included.tex', line: 3 },
      { severity: 'warning', kind: 'undefined-reference', message: "Reference `nowhere' on page 1 undefined.", path: 'main.tex', line: 3 },
      { severity: 'warning', kind: 'undefined-reference', message: "Reference `intro:missing' on page 1 undefined.", path: 'chapters/intro.tex', line: 2 },
      { severity: 'warning', kind: 'package:deeppkg', message: 'Raised in the deep file.', path: 'chapters/sections/deep.tex', line: 4 },
      { severity: 'warning', kind: 'package:spacepkg', message: 'Raised in the file with a space.', path: 'chapters/my intro.tex', line: 3 },
      { severity: 'warning', kind: 'undefined-citation', message: "Citation `nocite' on page 2 undefined.", path: 'chapters/included.tex', line: 2 },
      { severity: 'warning', kind: 'undefined-reference', message: "Reference `alsonowhere' on page 3 undefined.", path: 'main.tex', line: 13 },
      { severity: 'warning', kind: 'undefined-reference', message: 'There were undefined references.', path: 'main.tex' },
    ])
  })

  it('warnings: LaTeX, package (multi-line), class, font, project .sty; aux-file warnings go to main.tex', () => {
    const shape = engine === 'pdflatex' ? 'OT1/cmr' : 'TU/lmr' // Unicode engines use Latin Modern
    expect(brief('warnings', log)).toEqual([
      { severity: 'warning', kind: 'package:mystyle', message: 'Loaded from the project.', path: 'mystyle.sty', line: 3 },
      { severity: 'warning', kind: 'latex', message: 'Unused global option(s): [nosuchoption].', path: 'main.tex' },
      { severity: 'warning', kind: 'latex', message: "Label `dup' multiply defined.", path: 'main.tex' },
      { severity: 'warning', kind: 'package:hyperref', message: "Token not allowed in a PDF string (Unicode): removing `math shift'.", path: 'main.tex', line: 5 },
      { severity: 'warning', kind: 'package:hyperref', message: "Token not allowed in a PDF string (Unicode): removing `superscript'.", path: 'main.tex', line: 5 },
      { severity: 'warning', kind: 'undefined-reference', message: "Reference `sec:missing' on page 1 undefined.", path: 'main.tex', line: 6 },
      { severity: 'warning', kind: 'undefined-citation', message: "Citation `nobody' on page 1 undefined.", path: 'main.tex', line: 6 },
      { severity: 'warning', kind: 'font', message: `Font shape \`${shape}/bx/sc' undefined using \`${shape}/bx/n' instead.`, path: 'main.tex', line: 9 },
      { severity: 'warning', kind: 'package:mypkg', message: 'First line of the warning second line (with parens third line.', path: 'main.tex', line: 11 },
      { severity: 'warning', kind: 'class:myclass', message: 'A class warning.', path: 'main.tex', line: 12 },
      { severity: 'warning', kind: 'package:otherpkg', message: 'No line here.', path: 'main.tex' },
      { severity: 'warning', kind: 'font', message: 'Some font shapes were not available, defaults substituted.', path: 'main.tex' },
      { severity: 'warning', kind: 'undefined-reference', message: 'There were undefined references.', path: 'main.tex' },
      { severity: 'warning', kind: 'latex', message: 'There were multiply-defined labels.', path: 'main.tex' },
    ])
  })

  it('bad boxes: info with line ranges; box contents with parentheses do not disturb the file stack', () => {
    const d = brief('badboxes', log)
    expect(d.every(x => x.severity === 'info' && x.kind === 'badbox' && x.path === 'main.tex')).toBe(true)
    const byLine = (l: number | undefined) => d.filter(x => x.line === l).map(x => x.message.replace(/\([^)]*\)/, '(…)'))
    // two lines of that paragraph stick out, by different amounts: both are kept
    expect(byLine(4)).toEqual(['Overfull \\hbox (…) in paragraph', 'Overfull \\hbox (…) in paragraph'])
    expect(d.find(x => x.line === 4)?.endLine).toBe(5)
    expect(byLine(6)).toEqual(['Overfull \\hbox (…)'])
    expect(byLine(8)).toEqual(['Underfull \\hbox (…)'])
    expect(byLine(11).length).toBeGreaterThan(0)
    expect(byLine(14)).toEqual(['Overfull \\vbox (…)'])
    expect(byLine(16)).toEqual(['Underfull \\vbox (…)'])
    expect(byLine(18)).toEqual(['Overfull \\hbox (…) in alignment'])
    expect(d.find(x => x.line === 18)?.endLine).toBe(20)
    expect(byLine(undefined)).toEqual(['Overfull \\vbox (…) has occurred while \\output is active'])
  })

  it('missing package: missing-file error, then the emergency stop', () => {
    const d = brief('missing-file', log).filter(x => x.message !== 'No pages of output.')
    expect(d).toEqual([
      { severity: 'error', kind: 'missing-file', message: "File `doesnotexist.sty' not found.", path: 'main.tex' },
      { severity: 'error', kind: 'tex', message: 'Emergency stop (cannot \\read from terminal in nonstop modes)', path: 'main.tex', line: 4 },
    ])
  })

  it('no \\end{document}: emergency stop without file:line, attributed to the main file', () => {
    expect(brief('no-end', log)[0]).toEqual(
      { severity: 'error', kind: 'tex', message: 'Emergency stop (job aborted, no legal \\end found)', path: 'main.tex' })
  })

  it('empty document: "No pages of output" is an error', () => {
    expect(brief('empty', log)).toEqual([{ severity: 'error', kind: 'tex', message: 'No pages of output.', path: 'main.tex' }])
  })

  it('bibtex (latexmk console): .bib syntax error with line, warnings, undefined citations', () => {
    expect(brief('bibtex', `${engine}.console.log`)).toEqual([
      { severity: 'error', kind: 'bibtex', message: "I was expecting a `,' or a `}'", path: 'refs.bib', line: 15 },
      { severity: 'warning', kind: 'undefined-citation', message: "Citation `knuth' on page 1 undefined.", path: 'main.tex', line: 3 },
      { severity: 'warning', kind: 'undefined-citation', message: "Citation `incomplete' on page 1 undefined.", path: 'main.tex', line: 3 },
      { severity: 'warning', kind: 'undefined-citation', message: "Citation `missingkey' on page 1 undefined.", path: 'main.tex', line: 3 },
      { severity: 'warning', kind: 'undefined-reference', message: 'There were undefined references.', path: 'main.tex' },
      { severity: 'warning', kind: 'bibtex', message: 'I didn\'t find a database entry for "missingkey"' },
      { severity: 'warning', kind: 'bibtex', message: 'empty journal in incomplete', path: 'refs.bib' },
    ])
  })

  it('runaway argument with an unbalanced "(": later diagnostics stay in the right file', () => {
    expect(brief('runaway', log)).toEqual([
      { severity: 'error', kind: 'tex', message: 'Paragraph ended before \\short was complete.', path: 'ch/sub.tex', line: 3 },
      { severity: 'warning', kind: 'undefined-reference', message: "Reference `subref' on page 1 undefined.", path: 'ch/sub.tex', line: 4 },
      { severity: 'warning', kind: 'undefined-reference', message: "Reference `mainref' on page 1 undefined.", path: 'main.tex', line: 6 },
      { severity: 'warning', kind: 'undefined-reference', message: 'There were undefined references.', path: 'main.tex' },
    ])
  })

  it('fontspec: errors whose text is on the (fontspec) continuation lines keep their kind and text', () => {
    const errors = brief('fontspec', log).filter(x => x.severity === 'error')
    if (engine === 'pdflatex') {
      expect(errors[0]).toEqual({ severity: 'error', kind: 'package:fontspec', path: 'main.tex',
        message: 'The fontspec package requires either XeTeX or LuaTeX. You must change your typesetting engine to, e.g., "xelatex" or "lualatex" instead of "latex" or "pdflatex".' })
    } else {
      expect(errors[0]).toEqual({ severity: 'error', kind: 'package:fontspec', path: 'main.tex', line: 4,
        message: 'The font "NoSuchFontAtAll" cannot be found; this may be but usually is not a fontspec bug. Either there is a typo in the font name/file, the font is not installed (correctly), or there is a bug in the underlying font loading engine (XeTeX/luaotfload).' })
    }
  })

  it('bibtex warnings with natbib, .bib in a sub-folder', () => {
    expect(brief('bibtex-warn', log)).toEqual([
      { severity: 'warning', kind: 'undefined-citation', message: "Citation `missingkey' on page 1 undefined.", path: 'main.tex', line: 6 },
      { severity: 'warning', kind: 'undefined-citation', message: 'There were undefined citations.', path: 'main.tex' },
    ])
    const bib = brief('bibtex-warn', `${engine}.console.log`).filter(x => x.kind === 'bibtex')
    expect(bib).toEqual([
      { severity: 'warning', kind: 'bibtex', message: 'string name "undefinedmacro" is undefined', path: 'bib/refs.bib', line: 14 },
      { severity: 'warning', kind: 'bibtex', message: 'I didn\'t find a database entry for "missingkey"' },
      { severity: 'warning', kind: 'bibtex', message: 'empty journal in incomplete', path: 'bib/refs.bib' },
    ])
  })
})
